import math

def _rendezvous_slot_intervals(sandbox):
    return sandbox.get_reendezvous_slots()

def build_agent(sandbox):
    return sandbox.get_seeker_body()

def agent_action(sandbox, agent_body, step_count):
    if not hasattr(agent_body, '_state'):
        agent_body._state = {'last_tx': 0.0, 'last_ty': 0.0, 'tvx': 0.0, 'tvy': 0.0}
    state = agent_body._state
    tx, ty = sandbox.get_target_position()
    sx, sy = sandbox.get_seeker_position()
    svx, svy = sandbox.get_seeker_velocity()

    # Estimate target velocity using a more responsive filter
    if step_count % 5 == 0 and step_count > 5:
        dt = 5.0 / 60.0
        state['tvx'] = 0.2 * state['tvx'] + 0.8 * (tx - state['last_tx']) / dt
        state['tvy'] = 0.2 * state['tvy'] + 0.8 * (ty - state['last_ty']) / dt
        state['last_tx'], state['last_ty'] = tx, ty
    elif step_count <= 5:
        state['last_tx'], state['last_ty'] = tx, ty

    slots = _rendezvous_slot_intervals(sandbox)
    in_slot = any(lo <= step_count <= hi for (lo, hi) in slots)

    # Define goal position depending on phase
    if step_count < 110:
        gx, gy = 11.95, 1.35
    elif in_slot:
        gx, gy = tx, ty
    else:
        gx = 13.1 if (step_count // 120) % 2 == 0 else 13.5
        gy = 1.35

    # PD gains
    if in_slot:
        Kp = 200.0  # Position gain
        Kv = 150.0  # Velocity gain (velocity prioritized)
    else:
        Kp = 300.0
        Kv = -60.0

    # Compute desired acceleration using PD
    fx = Kp * (gx - sx) + Kv * (state['tvx'] - svx)
    fy = Kp * (gy - sy) + Kv * (state['tvy'] - svy)

    # Compute desired heading direction
    mag = math.hypot(fx, fy)
    if mag == 0:
        desired_heading = sandbox.get_seeker_heading()
    else:
        desired_heading = math.atan2(fy, fx)

    # Current heading and rotation
    current_heading = sandbox.get_seeker_heading()
    delta_theta = desired_heading - current_heading
    # Normalize to -π to π
    delta_theta = (delta_theta + math.pi) % (2 * math.pi) - math.pi

    # Apply rotation rate limit
    max_rotation = 0.12
    if delta_theta > max_rotation:
        actual_heading = current_heading + max_rotation
    elif delta_theta < -max_rotation:
        actual_heading = current_heading - max_rotation
    else:
        actual_heading = desired_heading

    # Cap thrust to avoid cooldown
    if mag > 90.0:
        mag = 90.0

    # Apply thrust in the actual heading direction
    thrust_x = mag * math.cos(actual_heading)
    thrust_y = mag * math.sin(actual_heading)

    sandbox.apply_seeker_force(thrust_x, thrust_y)
